class Patient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self.conditions = conditions
        self.severities = severities

    def get_total_conditions(self):
        return len(self.conditions)

    def get_average_severity(self):
        return sum(self.severities)/len(self.severities) if self.severities else 0

class Hospital:
    def __init__(self, patients, records):
        self.patients = patients  # {patient_id: Patient}
        self.records = records    # {patient_id: [record_dict]}

    def get_patient(self, patient_id):
