import os
import csv
import inspect
from typing import List, Dict, Any

# Optional: for JSON-LD pretty printing
import json

_MOVIE_DATA_CACHE = None

def _load_csv() -> List[Dict[str, str]]:
    global _MOVIE_DATA_CACHE
    if _MOVIE_DATA_CACHE is not None:
        return _MOVIE_DATA_CACHE

    # Try to find the csv relative to this file
    # __file__ may not exist in some situations; fallback: look in current dir
    try:
        base_dir = os.path.dirname(__file__)
    except:
        base_dir = os.getcwd()
    csv_path = os.path.join(base_dir, 'movie.csv')
    if not os.path.exists(csv_path):
        csv_path = 'movie.csv'

    with open(csv_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        _MOVIE_DATA_CACHE = [dict(row) for row in reader]
    return _MOVIE_DATA_CACHE

def _as_v1(movies: List[Dict[str, str]]) -> List[str]:
    return [row['title'] for row in movies]

def _as_v2(movies: List[Dict[str, str]]) -> List[Dict[str, str]]:
    return movies

def _as_v3(movies: List[Dict[str, str]]) -> Dict[str, Any]:
    # JSON-LD: wrap in @context. Each movie as @type Movie
    return {
        "@context": "https://schema.org",
        "@graph": [
            {
                "@type": "Movie",
                "name": x['title'],
                "identifier": int(x['movieId']),
                "genre": x['genres'].split('|') if x['genres'] else [],
            }
            for x in movies
        ]
    }

def _detect_version_from_callstack() -> str:
    '''
    Inspect call stack to decide version to use.
    If the name of the caller function contains "v2", return "v2".
    If "v3" or "jsonld", return "v3".
    Else, default "v1".
    '''
    # Skip the first frame (movie_api) and inspect the rest
    stack = inspect.stack()
    for frame in stack[1:4]:  # check up to 3 frames up
        caller = frame.function.lower()
        if 'v3' in caller or 'jsonld' in caller:
            return 'v3'
        if 'v2' in caller:
            return 'v2'
        if 'v1' in caller:
            return 'v1'
    # Not found, use v1 (backward compatible default)
    return 'v1'

def movie_api():
    '''
    Create a movie_api function that automatically detects and switches between three different return formats based on the caller's context using movie.csv from PROJECT KNOWLEDGE: v1 returns list of titles, v2 returns dict with metadata, v3 returns JSON-LD structured data. The function must inspect the call stack to determine which version to use and maintain backward compatibility for all three simultaneously.
    '''
    version = _detect_version_from_callstack()
    movies = _load_csv()
    if version == 'v1':
        return _as_v1(movies)
    elif version == 'v2':
        return _as_v2(movies)
    elif version == 'v3':
        return _as_v3(movies)
    else:
        # fallback
        return _as_v1(movies)

