import csv
import inspect
import os
import json

def movie_api():
    '''
    Automatically detects caller's context (v1, v2, v3) and returns:
      - v1: list of movie titles
      - v2: list of dict {movieId, title, genres}
      - v3: JSON-LD structured dict
    '''
    # --- 1. Load movies from CSV ---
    # Assume movie.csv is in the same dir as this file
    csv_path = os.path.join(os.path.dirname(__file__), 'movie.csv')
    movies = []
    with open(csv_path, newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            # Clean up and store
            movies.append({
                'movieId': int(row['movieId']),
                'title': row['title'],
                'genres': row['genres'].split('|') if row['genres'] else []
            })

    # --- 2. Detect caller version from stack ---
    stack = inspect.stack()
    caller_name = ""
    # Search one frame up (sometimes two, to be robust)
    for frame in stack[1:4]:
        caller_name = frame.function.lower()
        if 'v1' in caller_name:
            version = 'v1'
            break
        elif 'v2' in caller_name:
            version = 'v2'
            break
        elif 'v3' in caller_name:
            version = 'v3'
            break
    else:
        # Fallback: default to v1
        version = 'v1'

    # --- 3. Return appropriate structure ---
    if version == 'v1':
        # v1: list of titles
        return [movie['title'] for movie in movies]
    elif version == 'v2':
        # v2: list of dicts (shallow copy)
        return [dict(movieId=movie['movieId'], title=movie['title'], genres=movie['genres']) for movie in movies]
    elif version == 'v3':
        # v3: JSON-LD (root is @context & @graph)
        # Use schema.org/Movie
        jsonld = {
            "@context": "https://schema.org",
            "@graph": []
        }
        for movie in movies:
            jsonld["@graph"].append({
                "@type": "Movie",
                "identifier": movie['movieId'],
                "name": movie['title'],
                "genre": movie['genres'],
            })
        return jsonld

