    '''
    Create a performance_report function that reads performance_reviews.csv from PROJECT KNOWLEDGE. Parameters: employee_id (optional string), report_type (string, default 'summary'). RETURN TYPES AND FIELD SPECIFICATIONS: (1) summary mode - find CSV row where employee_id column matches parameter, return single dict with keys 'employee_id' (string value), 'overall_rating' (float from CSV column - keep as float not string), 'goals_status' (string from CSV column). (2) detailed mode - find matching row, return single dict with ALL CSV column names as keys preserving exact names and original types. (3) department mode - when employee_id is None, group rows by 'department' CSV column, return dict where keys are department names and values are dicts with 'avg_rating' (float - average of overall_rating column) and 'count' (int - number of employees).
    '''
    # -- Step 1: Map columns and correct types --
    TYPE_MAP = {
        'technical_score': int,
        'communication_score': int,
        'teamwork_score': int,
        'leadership_score': int,
        'overall_rating': float,
    }
    FILENAME = 'performance_reviews.csv'
    rows = []
    with open(FILENAME, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for r in reader:
            row = r.copy()
            for field, typ in TYPE_MAP.items():
                if row[field] != '':
                    row[field] = typ(row[field])
            rows.append(row)

    if employee_id:
        # -- Find the row --
        emp_row = None
        for row in rows:
            if row['employee_id'] == employee_id:
                emp_row = row
