                'goals_status': emp_row['goals_status'],
            }
        elif report_type == 'detailed':
            return emp_row
        else:
            raise ValueError("Invalid report_type for employee_id")
    else:
        # -- department mode --
        if report_type != 'department':
            raise ValueError("Must specify report_type='department' when employee_id is None")
        # Group by department
